# lib/static_index.py
# Auto-generated from public/index.html (see the 'make index module' step).
# The Vercel Python function reliably bundles .py files but not public/, so we
# serve this embedded copy when the on-disk public/index.html is unavailable.
INDEX_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>Citer - Speedy Citation Generator</title>\n    <style>\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n        }\n\n        :root {\n            --primary: #667eea;\n            --primary-dark: #5a6fd8;\n            --secondary: #764ba2;\n            --success: #10b981;\n            --warning: #f59e0b;\n            --error: #ef4444;\n            --bg-primary: #0f172a;\n            --bg-secondary: #1e293b;\n            --bg-tertiary: #334155;\n            --text-primary: #f8fafc;\n            --text-secondary: #cbd5e1;\n            --text-muted: #94a3b8;\n            --border: #475569;\n            --shadow: rgba(0, 0, 0, 0.25);\n            --glass: rgba(255, 255, 255, 0.05);\n        }\n\n        body {\n            font-family: \'Inter\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, sans-serif;\n            background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 100%);\n            min-height: 100vh;\n            color: var(--text-primary);\n            position: relative;\n            overflow-x: hidden;\n        }\n\n        body::before {\n            content: \'\';\n            position: fixed;\n            top: 0;\n            left: 0;\n            right: 0;\n            bottom: 0;\n            background: \n                radial-gradient(circle at 20% 80%, rgba(120, 119, 198, 0.3) 0%, transparent 50%),\n                radial-gradient(circle at 80% 20%, rgba(255, 255, 255, 0.1) 0%, transparent 50%),\n                radial-gradient(circle at 40% 40%, rgba(120, 119, 198, 0.2) 0%, transparent 50%);\n            pointer-events: none;\n            animation: float 20s ease-in-out infinite;\n        }\n\n        @keyframes float {\n            0%, 100% { transform: translateY(0px) rotate(0deg); }\n            50% { transform: translateY(-20px) rotate(1deg); }\n        }\n\n        .container {\n            max-width: 1200px;\n            margin: 0 auto;\n            padding: 2rem;\n            position: relative;\n            z-index: 1;\n        }\n\n        .header {\n            text-align: center;\n            margin-bottom: 3rem;\n            animation: fadeInUp 0.8s ease-out;\n        }\n\n        .header h1 {\n            font-size: 3.5rem;\n            font-weight: 800;\n            background: linear-gradient(135deg, #ffffff 0%, #cbd5e1 100%);\n            -webkit-background-clip: text;\n            -webkit-text-fill-color: transparent;\n            background-clip: text;\n            margin-bottom: 1rem;\n            letter-spacing: -0.02em;\n        }\n\n        .header p {\n            font-size: 1.25rem;\n            color: var(--text-secondary);\n            max-width: 600px;\n            margin: 0 auto;\n            line-height: 1.6;\n        }\n\n        .main-content {\n            display: grid;\n            grid-template-columns: 1fr 1fr;\n            gap: 2rem;\n            margin-bottom: 2rem;\n        }\n\n        .card {\n            background: var(--glass);\n            backdrop-filter: blur(20px);\n            border: 1px solid rgba(255, 255, 255, 0.1);\n            border-radius: 20px;\n            padding: 2rem;\n            box-shadow: 0 20px 40px var(--shadow);\n            transition: all 0.3s ease;\n            animation: fadeInUp 0.8s ease-out;\n        }\n\n        .card:hover {\n            transform: translateY(-5px);\n            box-shadow: 0 30px 60px var(--shadow);\n        }\n\n        .card h2 {\n            font-size: 1.5rem;\n            font-weight: 700;\n            margin-bottom: 1.5rem;\n            color: var(--text-primary);\n        }\n\n        .input-group {\n            margin-bottom: 1.5rem;\n        }\n\n        .input-group label {\n            display: block;\n            font-weight: 600;\n            margin-bottom: 0.5rem;\n            color: var(--text-secondary);\n            font-size: 0.9rem;\n            text-transform: uppercase;\n            letter-spacing: 0.05em;\n        }\n\n        .input-container {\n            position: relative;\n        }\n\n        .input-container input, .input-container select {\n            width: 100%;\n            padding: 1rem 1.5rem;\n            border: 2px solid transparent;\n            border-radius: 12px;\n            background: rgba(255, 255, 255, 0.1);\n            color: var(--text-primary);\n            font-size: 1rem;\n            transition: all 0.3s ease;\n            backdrop-filter: blur(10px);\n        }\n        \n        /* --- FIX 1: Dropdown Option Color --- */\n        .input-container select option {\n            color: #111;\n            background: #fff;\n        }\n\n        .input-container input:focus, .input-container select:focus {\n            outline: none;\n            border-color: var(--primary);\n            background: rgba(255, 255, 255, 0.15);\n            transform: translateY(-2px);\n            box-shadow: 0 10px 20px rgba(0, 0, 0, 0.1);\n        }\n\n        .input-container input::placeholder {\n            color: var(--text-muted);\n        }\n\n        .btn {\n            padding: 1rem 2rem;\n            border: none;\n            border-radius: 12px;\n            font-weight: 600;\n            font-size: 1rem;\n            cursor: pointer;\n            transition: all 0.3s ease;\n            text-transform: uppercase;\n            letter-spacing: 0.05em;\n            position: relative;\n            overflow: hidden;\n        }\n\n        .btn::before {\n            content: \'\';\n            position: absolute;\n            top: 0;\n            left: -100%;\n            width: 100%;\n            height: 100%;\n            background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.2), transparent);\n            transition: left 0.5s ease;\n        }\n\n        .btn:hover::before {\n            left: 100%;\n        }\n\n        .btn-primary {\n            background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);\n            color: white;\n            box-shadow: 0 10px 20px rgba(102, 126, 234, 0.3);\n        }\n\n        .btn-primary:hover {\n            transform: translateY(-3px);\n            box-shadow: 0 15px 30px rgba(102, 126, 234, 0.4);\n        }\n\n        .format-tabs {\n            display: flex;\n            gap: 0.5rem;\n            margin-bottom: 1.5rem;\n            background: rgba(255, 255, 255, 0.05);\n            padding: 0.5rem;\n            border-radius: 12px;\n        }\n\n        .format-tab {\n            flex: 1;\n            padding: 0.75rem 1rem;\n            border: none;\n            border-radius: 8px;\n            background: transparent;\n            color: var(--text-muted);\n            cursor: pointer;\n            transition: all 0.3s ease;\n            font-weight: 500;\n        }\n\n        .format-tab.active {\n            background: var(--primary);\n            color: white;\n            transform: translateY(-2px);\n            box-shadow: 0 5px 15px rgba(102, 126, 234, 0.3);\n        }\n\n        .output-area {\n            background: var(--bg-primary);\n            border: 1px solid var(--border);\n            border-radius: 12px;\n            padding: 1.5rem;\n            min-height: 200px;\n            font-family: \'Monaco\', \'Menlo\', \'Ubuntu Mono\', monospace;\n            font-size: 0.9rem;\n            line-height: 1.6;\n            position: relative;\n            overflow: auto;\n        }\n\n        .output-area.empty {\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            color: var(--text-muted);\n            font-style: italic;\n        }\n\n        .output-content {\n            white-space: pre-wrap;\n            word-break: break-word;\n        }\n\n        .copy-btn {\n            position: absolute;\n            top: 1rem;\n            right: 1rem;\n            padding: 0.5rem;\n            background: var(--primary);\n            border: none;\n            border-radius: 6px;\n            color: white;\n            cursor: pointer;\n            opacity: 0;\n            transition: all 0.3s ease;\n        }\n\n        .output-area:hover .copy-btn {\n            opacity: 1;\n        }\n\n        /* Secondary copy button ("copy without <ref> tags"), shown for Ref format. */\n        .copy-btn-template {\n            right: 3.6rem;\n        }\n\n        .loading {\n            display: inline-flex;\n            align-items: center;\n            gap: 0.5rem;\n        }\n\n        .spinner {\n            width: 20px;\n            height: 20px;\n            border: 2px solid transparent;\n            border-top: 2px solid currentColor;\n            border-radius: 50%;\n            animation: spin 1s linear infinite;\n        }\n\n        @keyframes spin {\n            to { transform: rotate(360deg); }\n        }\n\n        .status-message {\n            padding: 1rem;\n            border-radius: 12px;\n            margin: 1rem 0;\n            font-weight: 500;\n            display: none;\n        }\n\n        .status-message.success {\n            background: rgba(16, 185, 129, 0.1);\n            border: 1px solid var(--success);\n            color: var(--success);\n        }\n\n        .status-message.error {\n            background: rgba(239, 68, 68, 0.1);\n            border: 1px solid var(--error);\n            color: var(--error);\n        }\n\n        .search-history {\n            margin-top: 2rem;\n        }\n\n        .history-item {\n            background: rgba(255, 255, 255, 0.05);\n            border: 1px solid rgba(255, 255, 255, 0.1);\n            border-radius: 12px;\n            padding: 1rem;\n            margin-bottom: 1rem;\n            cursor: pointer;\n            transition: all 0.3s ease;\n        }\n\n        .history-item:hover {\n            background: rgba(255, 255, 255, 0.1);\n            transform: translateX(5px);\n        }\n\n        .history-query {\n            font-weight: 600;\n            margin-bottom: 0.5rem;\n        }\n\n        .history-meta {\n            font-size: 0.8rem;\n            color: var(--text-muted);\n        }\n\n        @keyframes fadeInUp {\n            from {\n                opacity: 0;\n                transform: translateY(30px);\n            }\n            to {\n                opacity: 1;\n                transform: translateY(0);\n            }\n        }\n\n        @media (max-width: 768px) {\n            .main-content {\n                grid-template-columns: 1fr;\n            }\n            .header h1 {\n                font-size: 2.5rem;\n            }\n            .container {\n                padding: 1rem;\n            }\n        }\n    </style>\n</head>\n<body>\n    <div class="container">\n        <div class="header">\n            <h1>Citer</h1>\n            <p>Speedy academic citation generator with SRU, IxTheo, and multiple format support</p>\n        </div>\n\n        <div class="main-content">\n            <div class="card">\n                <h2>🔍 Citation Search</h2>\n                \n                <div class="input-group">\n                    <label for="inputType">Input Type</label>\n                    <div class="input-container">\n                        <select id="inputType">\n                            <option value="">URL/DOI/ISBN (Auto-detect)</option>\n                            <option value="pmid">PMID</option>\n                            <option value="pmcid">PMCID</option>\n                            <option value="oclc">OCLC</option>\n                            <option value="sru">SRU Protocol</option>\n                            <option value="ixtheo">IxTheo Search</option>\n                        </select>\n                    </div>\n                </div>\n\n                <div class="input-group">\n                    <label for="userInput">Search Query</label>\n                    <div class="input-container">\n                        <input type="text" id="userInput" placeholder="Enter URL, DOI, ISBN, PMID, or search terms...">\n                    </div>\n                </div>\n\n                <div class="input-group">\n                    <label for="dateFormat">Date Format</label>\n                    <div class="input-container">\n                        <select id="dateFormat">\n                            <option value="%Y-%m-%d">2006-01-02 (ISO)</option>\n                            <option value="%d-%m-%Y">02-01-2006</option>\n                            <option value="%d %B %Y">2 January 2006</option>\n                            <option value="%B %d, %Y">January 2, 2006</option>\n                            <option value="%Y">2006 (year only)</option>\n                        </select>\n                    </div>\n                </div>\n\n                <div class="input-group">\n                    <label for="refName">Ref Name (optional)</label>\n                    <div class="input-container">\n                        <input type="text" id="refName" placeholder="Custom <ref name=&quot;...&quot;> (blank = auto)">\n                    </div>\n                </div>\n\n                <div class="input-group">\n                    <label style="display:flex;align-items:center;gap:0.5rem;cursor:pointer">\n                        <input type="checkbox" id="bulkMode" style="width:auto">\n                        Bulk input (one query per line)\n                    </label>\n                    <div class="input-container" id="bulkContainer" style="display:none;margin-top:0.5rem">\n                        <textarea id="bulkInput" rows="5" style="width:100%" placeholder="One DOI / ISBN / URL / query per line..."></textarea>\n                    </div>\n                </div>\n\n                <button class="btn btn-primary" id="searchBtn">\n                    <span class="btn-text">Generate Citation</span>\n                </button>\n\n                <div class="status-message" id="statusMessage"></div>\n            </div>\n\n            <div class="card">\n                <h2>📝 Citation Output</h2>\n                \n                <div class="format-tabs">\n                    <button class="format-tab active" data-format="custom">Custom</button>\n                    <button class="format-tab" data-format="cite">Cite</button>\n                    <button class="format-tab" data-format="ref">Ref</button>\n                    <button class="format-tab" data-format="sfn">SFN</button>\n                    <button class="format-tab" data-format="bibtex">BibTeX</button>\n                    <button class="format-tab" data-format="ris">RIS (Zotero)</button>\n                </div>\n\n                <div class="output-area empty" id="outputArea">\n                    <span>Enter a search query to generate citations</span>\n                    <button class="copy-btn" id="copyBtn" title="Copy to clipboard">📋</button>\n                </div>\n            </div>\n        </div>\n\n        <div class="card search-history">\n            <h2>📚 Search History</h2>\n            <div id="historyContainer">\n                <p style="color: var(--text-muted); font-style: italic;">No recent searches</p>\n            </div>\n        </div>\n    </div>\n\n    <script>\n        class ModernCiter {\n            constructor() {\n                this.searchCache = new Map();\n                this.searchHistory = JSON.parse(localStorage.getItem(\'citer_history\') || \'[]\');\n                this.currentFormat = \'custom\';\n                this.lastQuery = { inputType: null, userInput: null };\n                \n                this.initializeEventListeners();\n                this.renderHistory();\n            }\n\n            initializeEventListeners() {\n                document.getElementById(\'searchBtn\').addEventListener(\'click\', () => this.performSearch());\n                document.getElementById(\'userInput\').addEventListener(\'keypress\', (e) => {\n                    if (e.key === \'Enter\') this.performSearch();\n                });\n                document.querySelectorAll(\'.format-tab\').forEach(tab => {\n                    tab.addEventListener(\'click\', (e) => this.switchFormat(e.target.dataset.format));\n                });\n                document.getElementById(\'bulkMode\')?.addEventListener(\'change\', (e) => {\n                    document.getElementById(\'bulkContainer\').style.display = e.target.checked ? \'block\' : \'none\';\n                });\n                // Note: Copy button listener is re-attached in displayResult\n            }\n\n            async performSearch(isSwitchingFormat = false) {\n                const inputType = document.getElementById(\'inputType\').value;\n                const bulkMode = !!(document.getElementById(\'bulkMode\')?.checked);\n                let bulkLines = [];\n                let userInput = document.getElementById(\'userInput\').value.trim();\n                if (bulkMode) {\n                    bulkLines = (document.getElementById(\'bulkInput\')?.value || \'\')\n                        .split(\'\\n\').map(s => s.trim()).filter(Boolean);\n                    if (!bulkLines.length) {\n                        this.showMessage(\'Please enter at least one input line\', \'error\');\n                        return;\n                    }\n                    userInput = bulkLines.join(\'\\n\');\n                }\n\n                if (!userInput) {\n                    this.showMessage(\'Please enter a search query\', \'error\');\n                    return;\n                }\n\n                if (!isSwitchingFormat) {\n                    this.lastQuery = { inputType, userInput };\n                }\n\n                const dateFormat = document.getElementById(\'dateFormat\')?.value || \'%Y-%m-%d\';\n                const refName = (document.getElementById(\'refName\')?.value || \'\').trim();\n                const cacheKey = `${this.lastQuery.inputType}:${this.lastQuery.userInput}:${this.currentFormat}:${dateFormat}:${refName}`;\n                \n                if (this.searchCache.has(cacheKey)) {\n                    this.displayResult(this.searchCache.get(cacheKey));\n                    this.showMessage(\'Results loaded from cache\', \'success\');\n                    return;\n                }\n\n                this.setLoadingState(true);\n                \n                try {\n                    const params = {\n                        input_type: this.lastQuery.inputType,\n                        user_input: this.lastQuery.userInput,\n                        template_format: this.currentFormat,\n                        date_format: dateFormat,\n                        name: refName\n                    };\n                    if (bulkMode) params.inputs = bulkLines;\n                    const result = await this.callBackend(params);\n                    \n                    this.searchCache.set(cacheKey, result);\n                    this.displayResult(result);\n                    \n                    if (!isSwitchingFormat) {\n                        this.addToHistory({\n                            input_type: inputType,\n                            user_input: userInput,\n                            timestamp: new Date().toISOString()\n                        });\n                        this.showMessage(\'Citation generated successfully\', \'success\');\n                    } else {\n                         this.showMessage(\'Format switched successfully\', \'success\');\n                    }\n                } catch (error) {\n                    this.showMessage(`Error: ${error.message}`, \'error\');\n                    this.displayResult(\'Failed to generate citation. The server may have encountered an error.\');\n                } finally {\n                    this.setLoadingState(false);\n                }\n            }\n\n            async callBackend(params) {\n                const response = await fetch(\'/\', {\n                    method: \'POST\',\n                    headers: { \'Content-Type\': \'application/json\' },\n                    body: JSON.stringify(params)\n                });\n                \n                const responseText = await response.text();\n                if (!response.ok) {\n                    throw new Error(`HTTP ${response.status}: ${responseText || response.statusText}`);\n                }\n                \n                try {\n                    return JSON.parse(responseText);\n                } catch (e) {\n                    throw new Error("Received an invalid response from the server.");\n                }\n            }\n\n            displayResult(result) {\n                const outputArea = document.getElementById(\'outputArea\');\n                outputArea.classList.remove(\'empty\');\n                let content = \'\';\n                if (typeof result === \'string\') {\n                    content = result;\n                } else if (result && typeof result === \'object\') {\n                    content = JSON.stringify(result, null, 2);\n                } else {\n                    content = String(result || \'No result\');\n                }\n                \n                const outputContent = `<div class="output-content">${this.escapeHtml(content)}</div>`;\n                const copyButton = `<button class="copy-btn" id="copyBtn" title="Copy to clipboard">📋</button>`;\n                // In Ref format, also offer copying the {{cite ...}} without the\n                // enclosing <ref> tags (upstream #65).\n                const templateButton = this.currentFormat === \'ref\'\n                    ? `<button class="copy-btn copy-btn-template" id="copyTemplateBtn" title="Copy template without <ref> tags">📄</button>`\n                    : \'\';\n                outputArea.innerHTML = outputContent + copyButton + templateButton;\n                \n                document.getElementById(\'copyBtn\').addEventListener(\'click\', () => this.copyToClipboard());\n                if (this.currentFormat === \'ref\') {\n                    document.getElementById(\'copyTemplateBtn\').addEventListener(\'click\', () => this.copyTemplateOnly());\n                }\n            }\n\n            async switchFormat(format) {\n                this.currentFormat = format;\n                document.querySelectorAll(\'.format-tab\').forEach(tab => tab.classList.remove(\'active\'));\n                document.querySelector(`[data-format="${format}"]`).classList.add(\'active\');\n                if (this.lastQuery.userInput) {\n                    this.performSearch(true);\n                }\n            }\n\n            copyToClipboard() {\n                const outputContent = document.querySelector(\'.output-content\');\n                if (outputContent) {\n                    navigator.clipboard.writeText(outputContent.textContent)\n                        .then(() => this.showMessage(\'Citation copied to clipboard\', \'success\'))\n                        .catch(() => this.showMessage(\'Failed to copy citation\', \'error\'));\n                }\n            }\n\n            // Copy the {{cite ...}} template without the enclosing <ref> tags,\n            // for pasting into "Further reading" / bibliography sections (#65).\n            copyTemplateOnly() {\n                const outputContent = document.querySelector(\'.output-content\');\n                if (!outputContent) return;\n                let text = outputContent.textContent;\n                const m = text.match(/<ref\\b[^>]*>([\\s\\S]*?)<\\/ref>/);\n                if (m) text = m[1].trim();\n                navigator.clipboard.writeText(text)\n                    .then(() => this.showMessage(\'Template copied without ref tags\', \'success\'))\n                    .catch(() => this.showMessage(\'Failed to copy template\', \'error\'));\n            }\n\n            addToHistory(item) {\n                this.searchHistory = this.searchHistory.filter(h => h.user_input !== item.user_input);\n                this.searchHistory.unshift(item);\n                this.searchHistory = this.searchHistory.slice(0, 10);\n                localStorage.setItem(\'citer_history\', JSON.stringify(this.searchHistory));\n                this.renderHistory();\n            }\n\n            renderHistory() {\n                const container = document.getElementById(\'historyContainer\');\n                if (this.searchHistory.length === 0) {\n                    container.innerHTML = \'<p style="color: var(--text-muted); font-style: italic;">No recent searches</p>\';\n                    return;\n                }\n                container.innerHTML = this.searchHistory.map((item, index) => `\n                    <div class="history-item" data-index="${index}">\n                        <div class="history-query">${this.escapeHtml(item.user_input)}</div>\n                        <div class="history-meta">\n                            ${(item.input_type || \'AUTO\').toUpperCase()} • ${new Date(item.timestamp).toLocaleString()}\n                        </div>\n                    </div>\n                `).join(\'\');\n\n                container.querySelectorAll(\'.history-item\').forEach(item => {\n                    item.addEventListener(\'click\', (e) => {\n                        const index = e.currentTarget.dataset.index;\n                        this.loadFromHistory(parseInt(index, 10));\n                    });\n                });\n            }\n\n            loadFromHistory(index) {\n                const item = this.searchHistory[index];\n                if (item) {\n                    document.getElementById(\'userInput\').value = item.user_input;\n                    document.getElementById(\'inputType\').value = item.input_type;\n                    this.performSearch();\n                }\n            }\n\n            setLoadingState(loading) {\n                const btn = document.getElementById(\'searchBtn\');\n                const btnText = btn.querySelector(\'.btn-text\');\n                if (loading) {\n                    btn.disabled = true;\n                    btnText.innerHTML = \'<div class="loading"><div class="spinner"></div>Generating...</div>\';\n                } else {\n                    btn.disabled = false;\n                    btnText.textContent = \'Generate Citation\';\n                }\n            }\n\n            showMessage(message, type) {\n                const messageEl = document.getElementById(\'statusMessage\');\n                messageEl.textContent = message;\n                messageEl.className = `status-message ${type}`;\n                messageEl.style.display = \'block\';\n                \n                setTimeout(() => {\n                    messageEl.style.display = \'none\';\n                }, 3000);\n            }\n\n            escapeHtml(text) {\n                const div = document.createElement(\'div\');\n                div.textContent = text;\n                return div.innerHTML;\n            }\n        }\n        const citer = new ModernCiter();\n    </script>\n</body>\n</html>'
